import React from "react";
import { useLocation, Link, Navigate } from "react-router-dom";
import Navbar from "../components/Navbar";

const labelMap = {
  gender: "Gender", age: "Age", hypertension: "Hypertension",
  heart_disease: "Heart Disease", ever_married: "Ever Married",
  work_type: "Work Type", residence_type: "Residence Type",
  avg_glucose_level: "Avg Glucose (mg/dL)", bmi: "BMI",
  smoking_status: "Smoking Status",
};

export default function ResultPage() {
  const { state } = useLocation();
  if (!state?.result) return <Navigate to="/patient/predict" replace />;

  const { result, probability, inputData } = state;
  const isLikely = result === "Likely";

  return (
    <div className="page">
      <Navbar />
      <main className="container main-content">
        <div style={{ maxWidth: 700, margin: "0 auto" }}>
          {/* Risk card */}
          <div className={`card result-card`} style={{ marginBottom: "1.5rem", border: `2px solid ${isLikely ? "#fecaca" : "#bbf7d0"}`, background: isLikely ? "#fef2f2" : "#f0fdf4" }}>
            <div className="result-icon">{isLikely ? "⚠️" : "✅"}</div>
            <div className={`result-label ${isLikely ? "likely" : "not-likely"}`}>{result}</div>
            <div className="result-prob">Stroke Risk Probability: <strong>{probability}%</strong></div>
            {isLikely && (
              <div className="alert alert-warning" style={{ marginTop: "1rem", textAlign: "left" }}>
                <strong>Recommendation:</strong> Your results suggest a heightened stroke risk.
                Please consult a neurologist or physician as soon as possible.
              </div>
            )}
          </div>

          {/* Input summary */}
          <div className="card" style={{ marginBottom: "1.5rem" }}>
            <h3 className="card-title">Assessment Details</h3>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: ".6rem" }}>
              {Object.entries(inputData).map(([k, v]) => (
                <div key={k} style={{ display: "flex", justifyContent: "space-between", padding: ".5rem .8rem", background: "var(--bg)", borderRadius: 8, fontSize: ".88rem" }}>
                  <span style={{ color: "var(--text-muted)" }}>{labelMap[k] || k}</span>
                  <strong style={{ textTransform: "capitalize" }}>{v === "1" || v === 1 ? "Yes" : v === "0" || v === 0 ? "No" : String(v)}</strong>
                </div>
              ))}
            </div>
          </div>

          <div style={{ display: "flex", gap: "1rem" }}>
            <Link to="/patient/predict" className="btn btn-outline">Take Another Assessment</Link>
            <Link to="/patient/history" className="btn btn-primary">View History</Link>
            {isLikely && <Link to="/doctors" className="btn btn-danger">Find a Doctor</Link>}
          </div>
        </div>
      </main>
    </div>
  );
}
